import type { Vec3 } from '../contracts/math';
import type { CameraPose } from './CameraPose';
import { createCameraPose } from './CameraPose';
import type { EasingName } from './Easing';

/** The four viewpoints the match loop switches between. */
export type CameraMode = 'aim' | 'follow' | 'overview' | 'free';

export const CAMERA_MODES: readonly CameraMode[] = ['aim', 'follow', 'overview', 'free'];

export interface CameraModeSettings {
  /** Orbit radius the mode settles on. */
  distance: number;
  pitch: number;
  fov: number;
  /** Lift of the look-at point above the focus so the ball never hugs the bottom edge. */
  targetHeight: number;
  positionSmoothTime: number;
  targetSmoothTime: number;
  /** Blend length used when this mode takes over from another one. */
  transitionSeconds: number;
  easing: EasingName;
  /** Pointer orbit and zoom. */
  allowOrbit: boolean;
  /** WASD panning; only the free camera carries a target of its own. */
  allowPan: boolean;
}

/**
 * Per mode tuning. Aim sits close behind the ball, follow pulls back and up while
 * the ball rolls, overview flies out to show the whole hole before the first shot,
 * free lets the player leave the ball behind.
 */
export const CAMERA_MODE_SETTINGS: Readonly<Record<CameraMode, CameraModeSettings>> = {
  aim: {
    distance: 6.5,
    pitch: 0.38,
    fov: 55,
    targetHeight: 0.35,
    positionSmoothTime: 0.22,
    targetSmoothTime: 0.14,
    transitionSeconds: 0.7,
    easing: 'easeInOutCubic',
    allowOrbit: true,
    allowPan: false,
  },
  follow: {
    distance: 7.6,
    pitch: 0.46,
    fov: 58,
    targetHeight: 0.45,
    positionSmoothTime: 0.3,
    targetSmoothTime: 0.2,
    transitionSeconds: 0.5,
    easing: 'easeOutCubic',
    allowOrbit: true,
    allowPan: false,
  },
  overview: {
    distance: 18,
    pitch: 0.72,
    fov: 60,
    targetHeight: 0,
    positionSmoothTime: 0.5,
    targetSmoothTime: 0.4,
    transitionSeconds: 1.2,
    easing: 'easeInOutCubic',
    allowOrbit: false,
    allowPan: false,
  },
  free: {
    distance: 9,
    pitch: 0.5,
    fov: 60,
    targetHeight: 0,
    positionSmoothTime: 0.16,
    targetSmoothTime: 0.1,
    transitionSeconds: 0.45,
    easing: 'easeOutCubic',
    allowOrbit: true,
    allowPan: true,
  },
};

export function isCameraMode(value: string): value is CameraMode {
  return (CAMERA_MODES as readonly string[]).includes(value);
}

/** Mode defaults with caller overrides applied; undefined entries keep the default. */
export function cameraModeSettings(mode: CameraMode, overrides?: Partial<CameraModeSettings>): CameraModeSettings {
  const settings: CameraModeSettings = { ...CAMERA_MODE_SETTINGS[mode] };
  if (!overrides) return settings;
  const target = settings as unknown as Record<string, unknown>;
  for (const [key, value] of Object.entries(overrides)) {
    if (value !== undefined) target[key] = value;
  }
  return settings;
}

/** Everything the overview needs to frame a hole. */
export interface HoleFraming {
  bounds: { min: Vec3; max: Vec3 };
  spawn: Vec3;
  cup: Vec3;
}

export interface OverviewPoseOptions {
  yaw?: number;
  pitch?: number;
  fov?: number;
  /** Extra room around the level so the outer walls are not cropped. */
  margin?: number;
  minDistance?: number;
  maxDistance?: number;
}

const DEFAULT_MARGIN = 1.15;
const DEFAULT_MIN_OVERVIEW_DISTANCE = 8;
const DEFAULT_MAX_OVERVIEW_DISTANCE = 70;

const clamp = (value: number, min: number, max: number): number =>
  max < min ? min : Math.min(max, Math.max(min, value));

/** Yaw that points the camera from `from` towards `to` using the orbit convention. */
export function yawTowards(from: Vec3, to: Vec3): number {
  const dx = to.x - from.x;
  const dz = to.z - from.z;
  if (!Number.isFinite(dx) || !Number.isFinite(dz) || Math.abs(dx) + Math.abs(dz) < 1e-5) return Math.PI;
  return Math.atan2(-dx, -dz);
}

/** Look-at point of the overview: the middle of the footprint at play height. */
export function framingCenter(framing: HoleFraming): Vec3 {
  const { min, max } = framing.bounds;
  return {
    x: (min.x + max.x) / 2,
    y: clamp((framing.spawn.y + framing.cup.y) / 2, Math.min(min.y, max.y), Math.max(min.y, max.y)),
    z: (min.z + max.z) / 2,
  };
}

/** Half diagonal of the hole footprint; drives how far the overview stands back. */
export function framingRadius(framing: HoleFraming): number {
  const { min, max } = framing.bounds;
  const radius = Math.hypot(Math.abs(max.x - min.x), Math.abs(max.z - min.z)) / 2;
  return Number.isFinite(radius) ? radius : 0;
}

/** Camera pose that shows the level construction before the hole is played. */
export function overviewPose(framing: HoleFraming, options: OverviewPoseOptions = {}): CameraPose {
  const defaults = CAMERA_MODE_SETTINGS.overview;
  const fov = options.fov ?? defaults.fov;
  const pitch = options.pitch ?? defaults.pitch;
  const yaw = options.yaw ?? yawTowards(framing.spawn, framing.cup);
  const margin = options.margin ?? DEFAULT_MARGIN;
  const minDistance = options.minDistance ?? DEFAULT_MIN_OVERVIEW_DISTANCE;
  const maxDistance = options.maxDistance ?? DEFAULT_MAX_OVERVIEW_DISTANCE;

  const center = framingCenter(framing);
  const halfFov = Math.max(0.05, ((fov * Math.PI) / 180) / 2);
  const distance = clamp((framingRadius(framing) / Math.tan(halfFov)) * margin, minDistance, maxDistance);
  const cosPitch = Math.cos(pitch);

  return createCameraPose(
    {
      x: center.x + Math.sin(yaw) * cosPitch * distance,
      y: center.y + Math.sin(pitch) * distance,
      z: center.z + Math.cos(yaw) * cosPitch * distance,
    },
    center,
    fov,
  );
}
